package com.clavis.reader;
import android.content.Context;import android.net.Uri;import java.io.*;import java.net.URI;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import org.jsoup.Jsoup;import org.jsoup.nodes.*;import org.jsoup.parser.Parser;
/** Narrate semantic EPUB spine chapters, not captions and page-layout fragments. */
final class NarrationBook {
 static String read(ZipFile zip,String name)throws Exception{ZipEntry entry=zip.getEntry(name);if(entry==null)throw new IOException("Missing EPUB chapter");try(InputStream in=zip.getInputStream(entry);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>8*1024*1024)throw new IOException("EPUB chapter too large");out.write(b,0,n);}return out.toString("UTF-8");}}
 static String path(String base,String href){try{URI uri=URI.create("https://epub.invalid/"+base.replace(" ","%20")).resolve(href.replace(" ","%20")).normalize();return uri.getHost().equals("epub.invalid")?uri.getPath().substring(1):"";}catch(Exception e){return "";}}
 static String prose(String html){org.jsoup.nodes.Document doc=Jsoup.parse(html);doc.select("head,script,style,nav,figure,figcaption,.figcenter,.figleft,.figright,.illustration,img,svg,canvas,audio,video,[hidden],[aria-hidden=true],[role=doc-pagebreak],[epub:type=pagebreak]").remove();for(Element e:new ArrayList<>(doc.getAllElements())){String identity=(e.className()+" "+e.id()+" "+e.attr("epub:type")+" "+e.attr("role")).toLowerCase(Locale.ROOT);if(identity.matches(".*(?:caption|photo-credit|image-credit|imagecredit|illustration-credit).*"))e.remove();else if(e.attr("style").replace(" ","").matches("(?is).*(?:display:none|visibility:hidden).*"))e.remove();}StringBuilder out=new StringBuilder();walk(doc.body(),out);return NarrationText.clean(out.toString());}
 static void walk(Node node,StringBuilder out){if(node instanceof TextNode){out.append(((TextNode)node).getWholeText().replaceAll("\\s+"," "));return;}if(!(node instanceof Element))return;Element e=(Element)node;boolean block=e.tagName().matches("p|div|section|article|blockquote|h[1-6]|li|dt|dd|pre");if(block&&out.length()>0)out.append("\n\n");if(e.tagName().equals("br"))out.append('\n');for(Node child:e.childNodes())walk(child,out);if(block)out.append("\n\n");}
 static int anchor(String text,String anchor){String normalized=NarrationText.clean(anchor);String[] words=normalized.split("\\s+");for(int offset=0;offset<Math.min(36,words.length-3);offset+=6){int count=Math.min(8,words.length-offset);StringBuilder pattern=new StringBuilder();for(int n=0;n<count;n++){if(n>0)pattern.append("\\s+");pattern.append(java.util.regex.Pattern.quote(words[offset+n]));}java.util.regex.Matcher m=java.util.regex.Pattern.compile(pattern.toString(),java.util.regex.Pattern.CASE_INSENSITIVE|java.util.regex.Pattern.UNICODE_CASE).matcher(text);if(m.find())return m.start();}return -1;}
 static ListenSession epub(File source,String key,String title,int hint,String anchor)throws Exception{ArrayList<String> texts=new ArrayList<>(),titles=new ArrayList<>();ArrayList<Integer> indexes=new ArrayList<>();try(ZipFile zip=new ZipFile(source)){org.jsoup.nodes.Document container=Jsoup.parse(read(zip,"META-INF/container.xml"),"",Parser.xmlParser());String opf=container.select("rootfile").attr("full-path");org.jsoup.nodes.Document manifest=Jsoup.parse(read(zip,opf),"",Parser.xmlParser());HashMap<String,String> files=new HashMap<>();for(Element item:manifest.select("manifest > item"))files.put(item.id(),path(opf,item.attr("href")));int spine=0;for(Element item:manifest.select("spine > itemref")){String name=files.get(item.attr("idref"));int index=spine++;if(name==null||name.isEmpty()||item.attr("linear").equals("no"))continue;String html=read(zip,name),body=prose(html);if(body.isEmpty())continue;org.jsoup.nodes.Document chapter=Jsoup.parse(html);Element heading=chapter.selectFirst("h1,h2,h3");String label=heading==null?chapter.title():heading.text();if(label.trim().isEmpty())label="Chapter "+(texts.size()+1);split(body,label,index,texts,titles,indexes);}}
 if(texts.isEmpty())throw new IOException("No readable EPUB chapter text");int selected=0,offset=0;boolean found=false;if(!anchor.trim().isEmpty()){for(int n=0;n<texts.size();n++){int at=anchor(texts.get(n),anchor);if(at>=0){selected=n;offset=at;found=true;break;}}}if(!found)for(int n=0;n<indexes.size();n++)if(indexes.get(n)<=hint&&(n==0||!indexes.get(n).equals(indexes.get(n-1))))selected=n;
 ListenSession story=new ListenSession(key,title,"");story.chapters=true;StringBuilder text=new StringBuilder();for(int n=selected;n<texts.size();n++){if(text.length()>0)text.append("\n\n");story.starts.add(text.length());story.labels.add(titles.get(n));story.spines.add(indexes.get(n));text.append(n==selected?texts.get(n).substring(offset):texts.get(n));if(text.length()>8*1024*1024)throw new IOException("Book is too large to prepare at once");}story.text=text.toString();return story;}
 static void split(String body,String label,int index,ArrayList<String> texts,ArrayList<String> titles,ArrayList<Integer> indexes){java.util.regex.Matcher headers=java.util.regex.Pattern.compile("(?im)^(?:chapter|book|part)[ \\t]+(?:[IVXLCDM]+|\\d+)\\b[^\\n]{0,120}$").matcher(body);ArrayList<Integer> starts=new ArrayList<>();ArrayList<String> names=new ArrayList<>();while(headers.find()){starts.add(headers.start());names.add(headers.group().trim());}if(starts.size()<2){texts.add(body);titles.add(label);indexes.add(index);return;}if(starts.get(0)>0){String prefix=body.substring(0,starts.get(0)).trim();if(!prefix.isEmpty()){texts.add(prefix);titles.add(label);indexes.add(index);}}for(int n=0;n<starts.size();n++){texts.add(body.substring(starts.get(n),n+1<starts.size()?starts.get(n+1):body.length()).trim());titles.add(names.get(n));indexes.add(index);}}
 static ListenSession upgrade(Context c,ListenSession old)throws Exception{if(!old.key.startsWith("book:")||(old.chapters&&!old.spines.isEmpty()&&old.spines.get(0)>=0))return old;int end=old.key.lastIndexOf(':');if(end<=5)return old;String uri=old.key.substring(5,end);File copy=File.createTempFile("listen-chapters-",".epub",c.getCacheDir());try{try(InputStream in=c.getContentResolver().openInputStream(Uri.parse(uri));OutputStream out=new FileOutputStream(copy)){if(in==null)return old;byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}try(ZipFile zip=new ZipFile(copy)){if(zip.getEntry("META-INF/container.xml")==null)return old;}String anchor=old.text.substring(Math.min(old.position,old.text.length()),Math.min(old.text.length(),old.position+500));ListenSession updated=epub(copy,old.key,old.title,0,anchor);if(!anchor.isEmpty()&&anchor(updated.text,anchor)<0)return old;return updated;}finally{copy.delete();}}
}
